const maintenant = DateTime.now().setZone('Europe/Paris');
const dateEdition = maintenant.toFormat('yyyy-LL-dd');
const limite = maintenant.minus({ hours: 48 });
const noms = {
  'openai.com': 'OpenAI', 'blog.google': 'Google AI', 'huggingface.co': 'Hugging Face', 'github.blog': 'GitHub Changelog',
  'notion.com': 'Notion', 'linear.app': 'Linear', 'vercel.com': 'Vercel', 'techcrunch.com': 'TechCrunch',
  'theverge.com': 'The Verge', 'lennysnewsletter.com': "Lenny's Newsletter", 'producthunt.com': 'Product Hunt', 'news.google.com': 'Google Actualités'
};
const boursiers = /finance|benzinga|tradingview|marketscreener|barron|motley|investing\.com|seeking alpha|tikr|marketwatch|zacks|nasdaq|stocktitan|insidermonkey|gurufocus|pymnts|ecofin/i;
const sourceDe = (url) => {
  const m = String(url).match(/^https?:\/\/([^\/?#:]+)/i);
  if (!m) return 'Source';
  const h = m[1].toLowerCase().replace(/^www\./, '');
  for (const d in noms) { if (h === d || h.endsWith('.' + d)) return noms[d]; }
  return h;
};
const propre = (t) => String(t || '').replace(/<[^>]*>/g, ' ').replace(/&#(\d+);/g, (m, n) => String.fromCharCode(Number(n))).replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&rsquo;/g, "'").replace(/&quot;/g, '"').replace(/\s+/g, ' ').trim();
const vus = new Set();
const parSource = {};
let googleActu = 0;
const sortie = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const a = items[i].json;
  if (!a || !a.link || !a.title) continue;
  const d = DateTime.fromISO(a.isoDate || '', { zone: 'utc' });
  if (!d.isValid || d < limite || d > maintenant.plus({ hours: 2 })) continue;
  const url = String(a.link).trim();
  if (vus.has(url)) continue;
  vus.add(url);
  let source = sourceDe(url);
  let titre = propre(a.title);
  if (source === 'Google Actualités') {
    const m = titre.match(/^(.*) - ([^-]+)$/);
    if (m) { titre = m[1].trim(); source = m[2].trim(); }
    if (boursiers.test(source)) continue;
    googleActu = googleActu + 1;
    if (googleActu > 12) continue;
  }
  parSource[source] = (parSource[source] || 0) + 1;
  if (parSource[source] > 8) continue;
  let extrait = propre(a.contentSnippet || a.content || a.summary || '').replace(/The post .* appeared first on .*$/, '').trim();
  if (/^Discussion \| Link$/.test(extrait)) extrait = '';
  sortie.push({ date_edition: dateEdition, titre: titre.slice(0, 300), source, url, date_pub: d.toISO(), extrait: extrait.slice(0, 600) });
}
sortie.sort((x, y) => (x.date_pub < y.date_pub ? 1 : -1));
return sortie.slice(0, 80).map((j, k) => ({ json: { ...j, cid: 'c' + (k + 1) } }));
